import { collapse, decodeWord, tokenize, type Token } from './headers.ts';

export interface Mailbox {
  kind: 'mailbox';
  name: string;
  address: string;
}
export interface Group {
  kind: 'group';
  members: Mailbox[];
}
export interface AddressList {
  addresses: (Mailbox | Group)[];
  error: boolean;
}
export function addresses(text: string): AddressList | undefined {
  const tokens = tokenize(text, 'address');
  if (!tokens?.length) return undefined;
  let index = 0;
  let error = false;
  const collect = (phrase: boolean): Token[] => {
    const result: Token[] = [];
    while (
      tokens[index]?.kind === 'word' ||
      tokens[index]?.kind === '.' ||
      (phrase && tokens[index]?.kind === 'quoted')
    ) {
      result.push(tokens[index++]);
    }
    return result;
  };
  const validPart = (part: Token[]) =>
    part.length > 0 &&
    part.length % 2 === 1 &&
    part.every((t, i) => t.kind === (i % 2 ? '.' : 'word'));
  const display = (phrase: Token[]): string => {
    let name = '';
    let previousSuccess = false;
    phrase.forEach((token, i) => {
      const decoded =
        token.kind === 'word'
          ? decodeWord(token.text)
          : { text: token.text, success: false, error: false };
      if (i && token.preceded && !(previousSuccess && decoded.success)) name += ' ';
      name += decoded.text;
      previousSuccess = decoded.success;
      error ||= decoded.error;
    });
    return collapse(name);
  };
  const readAddress = (inside: boolean): Mailbox | Group | undefined => {
    const phrase = collect(true);
    if (tokens[index]?.kind === ':' && phrase.length && !inside) {
      index++;
      const members: Mailbox[] = [];
      if (tokens[index]?.kind !== ';') {
        while (true) {
          const member = readAddress(true);
          if (!member || member.kind !== 'mailbox') return undefined;
          members.push(member);
          if (tokens[index]?.kind !== ',') break;
          index++;
        }
      }
      if (tokens[index]?.kind !== ';') return undefined;
      index++;
      return { kind: 'group', members };
    }
    let local: Token[];
    let name = '';
    let angle = false;
    if (tokens[index]?.kind === '<') {
      angle = true;
      index++;
      local = collect(false);
      name = display(phrase);
    } else if (tokens[index]?.kind === '@') local = phrase;
    else return undefined;
    if (!validPart(local) || tokens[index]?.kind !== '@') return undefined;
    index++;
    const domain = collect(false);
    if (!validPart(domain)) return undefined;
    if (angle) {
      if (tokens[index]?.kind !== '>') return undefined;
      index++;
    }
    return {
      kind: 'mailbox',
      name,
      address: (
        local.map((t) => t.text).join('') +
        '@' +
        domain.map((t) => t.text).join('')
      ).toLowerCase(),
    };
  };
  const result: (Mailbox | Group)[] = [];
  while (true) {
    const address = readAddress(false);
    if (!address) return undefined;
    result.push(address);
    if (index === tokens.length) return { addresses: result, error };
    if (tokens[index]?.kind !== ',') return undefined;
    index++;
  }
}

import { removeComments, strip } from './headers.ts';

const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const weekdays = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const zones: Record<string, number> = {
  ut: 0,
  gmt: 0,
  z: 0,
  est: -300,
  edt: -240,
  cst: -360,
  cdt: -300,
  mst: -420,
  mdt: -360,
  pst: -480,
  pdt: -420,
};
const leap = (year: number) => year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
function monthDays(year: number, month: number): number {
  return month === 1 ? (leap(year) ? 29 : 28) : [3, 5, 8, 10].includes(month) ? 30 : 31;
}
export type ParsedDate = { seconds: number } | { problem: string };
export function parseDate(text: string): ParsedDate {
  const syntax = { problem: 'bad Date syntax' };
  const range = { problem: 'Date out of range' };
  const uncommented = removeComments(text);
  if (uncommented === undefined) return syntax;
  const tokens = strip(uncommented.replaceAll(',', ' , '))
    .split(/[ \t]+/)
    .filter(Boolean);
  let weekday = -1;
  if (tokens.length >= 3 && weekdays.includes(tokens[0].toLowerCase()) && tokens[1] === ',') {
    weekday = weekdays.indexOf(tokens.splice(0, 2)[0].toLowerCase());
  }
  if (tokens.length !== 5) return syntax;
  const [dayText, monthText, yearText, timeText, zoneText] = tokens;
  const month = months.indexOf(monthText.toLowerCase());
  const time = timeText.split(':');
  const numericZone = /^[+-][0-9]{4}$/.test(zoneText);
  const zoneName = zoneText.toLowerCase();
  if (
    !/^[0-9]{1,2}$/.test(dayText) ||
    month < 0 ||
    !/^([0-9]{2}|[0-9]{4})$/.test(yearText) ||
    (time.length !== 2 && time.length !== 3) ||
    time.some((t) => !/^[0-9]{2}$/.test(t)) ||
    (!numericZone && !Object.hasOwn(zones, zoneName))
  ) {
    return syntax;
  }
  let year = +yearText;
  if (yearText.length === 2) year += year < 50 ? 2000 : 1900;
  const day = +dayText;
  const hour = +time[0];
  const minute = +time[1];
  const second = +(time[2] ?? 0);
  let offset = zones[zoneName];
  if (numericZone) {
    const hours = +zoneText.slice(1, 3);
    const minutes = +zoneText.slice(3);
    if (hours > 23 || minutes > 59) return range;
    offset = (hours * 60 + minutes) * (zoneText[0] === '-' ? -1 : 1);
  }
  if (
    year < 1970 ||
    year > 2099 ||
    day < 1 ||
    day > monthDays(year, month) ||
    hour > 23 ||
    minute > 59 ||
    second > 59
  ) {
    return range;
  }
  let days = 0;
  for (let y = 1970; y < year; y++) days += leap(y) ? 366 : 365;
  for (let m = 0; m < month; m++) days += monthDays(year, m);
  days += day - 1;
  const seconds = days * 86400 + hour * 3600 + minute * 60 + second - offset * 60;
  if (seconds < 0) return range;
  if (weekday >= 0 && (days + 3) % 7 !== weekday) return { problem: 'Date weekday mismatch' };
  return { seconds };
}
export function formatDate(seconds: number): string {
  let days = Math.floor(seconds / 86400);
  let year = 1970;
  let month = 0;
  while (days >= (leap(year) ? 366 : 365)) {
    days -= leap(year) ? 366 : 365;
    year++;
  }
  while (days >= monthDays(year, month)) {
    days -= monthDays(year, month);
    month++;
  }
  const remainder = seconds % 86400;
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${year}-${pad(month + 1)}-${pad(days + 1)} ${pad(Math.floor(remainder / 3600))}:${pad(Math.floor((remainder % 3600) / 60))}:${pad(remainder % 60)}`;
}

import { strictBase64 } from './mime.ts';

export interface SourceLine {
  text: string;
  number: number;
}
export interface Field {
  name: string;
  value: string;
}
export interface Header {
  fields: Field[];
  invalid: number[];
}
export const strip = (text: string) => text.replace(/^[ \t]+|[ \t]+$/g, '');
export const collapse = (text: string) => strip(text.replace(/[ \t]+/g, ' '));
export function parseHeaders(lines: SourceLine[]): Header {
  const fields: Field[] = [];
  const invalid: number[] = [];
  let previous: Field | undefined;
  for (const line of lines) {
    if (/^[ \t]/.test(line.text)) {
      if (previous) previous.value += line.text;
      else invalid.push(line.number);
      continue;
    }
    const colon = line.text.indexOf(':');
    if (colon <= 0 || /[^\x21-\x7e]/.test(line.text.slice(0, colon))) {
      invalid.push(line.number);
      previous = undefined;
    } else {
      previous = {
        name: line.text.slice(0, colon).toLowerCase(),
        value: line.text.slice(colon + 1),
      };
      fields.push(previous);
    }
  }
  for (const field of fields) field.value = strip(field.value);
  return { fields, invalid };
}
export function field(fields: Field[], name: string): string | undefined {
  return fields.find((f) => f.name === name.toLowerCase())?.value;
}
export function removeComments(text: string): string | undefined {
  let depth = 0;
  let output = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (depth === 0) {
      if (c === '(') {
        depth = 1;
        output += ' ';
      } else output += c;
    } else if (c === '\\') i++;
    else if (c === '(') depth++;
    else if (c === ')') depth--;
  }
  return depth === 0 ? output : undefined;
}
export interface DecodedWord {
  text: string;
  success: boolean;
  error: boolean;
}
export function decodeWord(word: string): DecodedWord {
  const original = { text: word, success: false, error: false };
  if (word.length < 4 || !word.startsWith('=?') || !word.endsWith('?=')) return original;
  const pieces = word.slice(2, -2).split('?');
  if (pieces.length !== 3 || pieces.some((piece) => piece === '')) return original;
  const [charset, encoding, data] = pieces;
  let decoded: string | undefined;
  if (charset.toLowerCase() === 'us-ascii') {
    if (encoding.toLowerCase() === 'b') decoded = strictBase64(data);
    else if (encoding.toLowerCase() === 'q') {
      decoded = '';
      for (let i = 0; i < data.length; i++) {
        if (data[i] === '_') decoded += ' ';
        else if (data[i] === '=') {
          const hex = data.slice(i + 1, i + 3);
          if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
            decoded = undefined;
            break;
          }
          decoded += String.fromCharCode(parseInt(hex, 16));
          i += 2;
        } else decoded += data[i];
      }
    }
  }
  if (decoded === undefined || /[^\x20-\x7e]/.test(decoded)) return { ...original, error: true };
  return { text: decoded, success: true, error: false };
}
export function unstructured(text: string): { text: string; error: boolean } {
  const words = strip(text)
    .split(/[ \t]+/)
    .filter(Boolean);
  let output = '';
  let previousSuccess = false;
  let error = false;
  words.forEach((word, i) => {
    const decoded = decodeWord(word);
    if (i && !(previousSuccess && decoded.success)) output += ' ';
    output += decoded.text;
    previousSuccess = decoded.success;
    error ||= decoded.error;
  });
  return { text: collapse(output), error };
}
export interface Token {
  kind: string;
  text: string;
  preceded: boolean;
}
export function tokenize(text: string, variant: 'address' | 'mime'): Token[] | undefined {
  const tokens: Token[] = [];
  const specials = variant === 'address' ? '<>:;@,.' : '/;=';
  const isWord = (c: string) =>
    variant === 'address'
      ? /^[A-Za-z0-9!#$%&'*+\/=?^_`{|}~-]$/.test(c)
      : c.charCodeAt(0) >= 33 && c.charCodeAt(0) <= 126 && !'()<>@,;:\\"/[]?='.includes(c);
  let i = 0;
  let preceded = false;
  while (i < text.length) {
    const c = text[i];
    if (c === ' ' || c === '\t') {
      preceded = true;
      i++;
      continue;
    }
    if (c === '(') {
      preceded = true;
      let depth = 1;
      i++;
      while (i < text.length && depth > 0) {
        if (text[i] === '\\') i += 2;
        else {
          if (text[i] === '(') depth++;
          else if (text[i] === ')') depth--;
          i++;
        }
      }
      if (depth) return undefined;
      continue;
    }
    let kind: string;
    let value = '';
    if (c === '"') {
      kind = 'quoted';
      i++;
      while (i < text.length && text[i] !== '"') {
        if (text[i] === '\\') {
          i++;
          if (i >= text.length) return undefined;
        }
        value += text[i++];
      }
      if (i >= text.length) return undefined;
      i++;
    } else if (specials.includes(c)) {
      kind = c;
      value = c;
      i++;
    } else if (isWord(c)) {
      kind = 'word';
      while (i < text.length && isWord(text[i])) value += text[i++];
    } else return undefined;
    tokens.push({ kind, text: value, preceded });
    preceded = false;
  }
  return tokens;
}
export interface ParameterValue {
  type: string;
  subtype: string;
  parameters: Map<string, string>;
}
export function parameters(text: string, subtype: boolean): ParameterValue | undefined {
  const tokens = tokenize(text, 'mime');
  if (!tokens || tokens[0]?.kind !== 'word') return undefined;
  const value: ParameterValue = {
    type: tokens[0].text.toLowerCase(),
    subtype: '',
    parameters: new Map(),
  };
  let i = 1;
  if (subtype) {
    if (tokens[i]?.kind !== '/' || tokens[i + 1]?.kind !== 'word') return undefined;
    value.subtype = tokens[i + 1].text.toLowerCase();
    i += 2;
  }
  while (i < tokens.length) {
    if (
      tokens[i]?.kind !== ';' ||
      tokens[i + 1]?.kind !== 'word' ||
      tokens[i + 2]?.kind !== '=' ||
      (tokens[i + 3]?.kind !== 'word' && tokens[i + 3]?.kind !== 'quoted')
    ) {
      return undefined;
    }
    const name = tokens[i + 1].text.toLowerCase();
    if (!value.parameters.has(name)) value.parameters.set(name, tokens[i + 3].text);
    i += 4;
  }
  return value;
}

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { addresses, type Mailbox } from './addresses.ts';
import { formatDate, parseDate } from './dates.ts';
import {
  field,
  parameters,
  parseHeaders,
  removeComments,
  unstructured,
  type Field,
  type SourceLine,
} from './headers.ts';
import { base64Body, quotedPrintable } from './mime.ts';
import { buildThreads, type Container, type ThreadMessage } from './threader.ts';

interface Entity {
  number: string;
  type: string;
  subtype: string;
  parameters: Map<string, string>;
  disposition?: string;
  filename?: string;
  children?: Entity[];
  content: string;
}
interface Message extends ThreadMessage {
  problems: string[];
  sender?: Mailbox;
  to: string[];
  cc: string[];
  subject: string;
  seconds?: number;
  entity: Entity;
  thread: number;
  depth: number;
  parent?: Message;
}
const trailing = (text: string) => text.replace(/[ \t]+$/, '');
function inputLines(path: string): string[] {
  return readFileSync(path, 'ascii').slice(0, -1).split('\n');
}
function sections(lines: SourceLine[]): { headers: SourceLine[]; body: SourceLine[] } {
  const blank = lines.findIndex((line) => line.text === '');
  return blank < 0
    ? { headers: lines, body: [] }
    : { headers: lines.slice(0, blank), body: lines.slice(blank + 1) };
}
function wellFormedId(text: string): boolean {
  if (text.length < 3 || text[0] !== '<' || !text.endsWith('>')) return false;
  const inside = text.slice(1, -1);
  const at = inside.indexOf('@');
  return (
    at > 0 &&
    at < inside.length - 1 &&
    inside.indexOf('@', at + 1) < 0 &&
    !/[^\x21-\x7e]|[<>()"\\]/.test(inside)
  );
}
function extractIds(text: string): string[] {
  const ids: string[] = [];
  let start = text.indexOf('<');
  while (start >= 0) {
    const end = text.indexOf('>', start + 1);
    if (end < 0) break;
    const id = text.slice(start, end + 1);
    if (wellFormedId(id)) ids.push(id);
    start = text.indexOf('<', end + 1);
  }
  return ids;
}
function parseEntity(
  number: string,
  fields: Field[],
  body: SourceLine[],
  enabled: boolean,
  problems: string[],
): Entity {
  const entity: Entity = {
    number,
    type: 'text',
    subtype: 'plain',
    parameters: new Map(),
    content: '',
  };
  const contentType = field(fields, 'content-type');
  const disposition = field(fields, 'content-disposition');
  if (enabled && contentType !== undefined) {
    const parsed = parameters(contentType, true);
    if (!parsed) problems.push(`bad Content-Type in part ${number}`);
    else {
      entity.type = parsed.type;
      entity.subtype = parsed.subtype;
      entity.parameters = parsed.parameters;
    }
  }
  if (enabled && disposition !== undefined) {
    const parsed = parameters(disposition, false);
    if (!parsed) problems.push(`bad Content-Disposition in part ${number}`);
    else {
      entity.disposition = parsed.type;
      entity.filename = parsed.parameters.get('filename');
    }
  }
  if (!entity.filename) entity.filename = entity.parameters.get('name');
  const charset = entity.parameters.get('charset');
  if (entity.type === 'text' && charset !== undefined && charset.toLowerCase() !== 'us-ascii') {
    problems.push(`unsupported charset "${charset.toLowerCase()}" in part ${number}`);
  }
  if (enabled && entity.type === 'multipart') {
    const boundary = entity.parameters.get('boundary');
    if (!boundary) problems.push(`missing boundary in part ${number}`);
    else {
      const parts: SourceLine[][] = [];
      let closed = false;
      for (const line of body) {
        const text = trailing(line.text);
        if (text === `--${boundary}--`) {
          closed = true;
          break;
        }
        if (text === `--${boundary}`) parts.push([]);
        else if (parts.length) parts[parts.length - 1].push(line);
      }
      if (!parts.length) problems.push(`no parts in part ${number}`);
      else if (!closed) problems.push(`unterminated multipart in part ${number}`);
      entity.children = parts.map((lines, i) => {
        const split = sections(lines);
        const header = parseHeaders(split.headers);
        for (const line of header.invalid) problems.push(`bad header line ${line}`);
        return parseEntity(`${number}.${i + 1}`, header.fields, split.body, true, problems);
